@layer nz.tokens, nz.themes, nz.reset, nz.base, nz.components, nz.patterns, nz.utilities;

/* @nizivo/react/css/top-bar.css (Figma Top Bar 755:1031, figma/06 §6.8): 32 px inline padding, 24
   between the title, the search and the actions, bg/canvas over a border/subtle line. Figma's 14 px
   block padding is off the scale and its height 71 px: 16 px around a 40 px control gives 72 + 1.
   The title takes the free width (Heading/H3) and keeps its own, up to half the bar; the search is
   360 px at most and shrinks first. Public --nz-top-bar-* hooks are read once, at the property. */
@layer nz.components {
  .nz-top-bar {
    display: flex;
    align-items: center;
    gap: var(--nz-top-bar-gap, var(--nz-space-6));
    box-sizing: border-box;
    min-inline-size: 0;
    padding-block: var(--nz-space-4);
    padding-inline: var(--nz-top-bar-padding-inline, var(--nz-grid-margin));
    border-block-end: var(--nz-border-width-default) solid
      var(--nz-top-bar-border, var(--nz-border-subtle));
    background: var(--nz-top-bar-bg, var(--nz-bg-canvas));
    color: var(--nz-text-primary);
  }

  /* the title keeps its width, up to half the bar (then an ellipsis); the search gives way first */
  .nz-top-bar-start {
    display: flex;
    flex: 1 0 auto;
    align-items: center;
    min-inline-size: 0;
    max-inline-size: 50%;
  }

  .nz-top-bar-title {
    overflow: hidden;
    font: var(--nz-font-heading-h3);
    letter-spacing: var(--nz-tracking-heading-h3);
    text-overflow: ellipsis;
    white-space: nowrap;
  }

  .nz-top-bar-search {
    flex: 0 1 var(--nz-top-bar-search-width, 22.5rem);
    min-inline-size: 0;
  }

  .nz-top-bar-actions {
    display: flex;
    flex: none;
    align-items: center;
    gap: var(--nz-space-3);
  }

  @media (forced-colors: active) {
    .nz-top-bar {
      border-block-end-color: CanvasText;
    }
  }
}
